import json,subprocess,hashlib
from pathlib import Path
root=Path('/var/lib/forum-flow/recovery-all-20261123');unit=Path('/etc/systemd/system/forum-flow.service');original=(root/'before-catchup-forum-flow.service').read_bytes();lines=original.decode().splitlines(keepends=True);indexes=[i for i,l in enumerate(lines) if l.startswith('ExecStart=')];assert len(indexes)==1;i=indexes[0];bad=lines.copy();bad[i]=bad[i].rstrip(chr(92)+'r'+chr(92)+'n')+' --max-catchup-topics-per-site 12'+chr(92)+'n';assert unit.read_bytes()==''.join(bad).encode(),'CATCHUP_UNIT_CHANGED';lines[i]=lines[i].rstrip(chr(13)+chr(10))+' --max-catchup-topics-per-site 12'+chr(10);unit.write_bytes(''.join(lines).encode());subprocess.run(['systemctl','daemon-reload'],check=True);subprocess.run(['systemctl','restart','forum-flow'],check=True);pid=int(subprocess.check_output(['systemctl','show','forum-flow','-p','MainPID','--value'],text=True));args=Path('/proc/'+str(pid)+'/cmdline').read_bytes().decode().split(chr(0));idx=args.index('--max-catchup-topics-per-site');assert args[idx+1]=='12';normal=args[args.index('--max-topics-per-site')+1];assert normal=='4';out={'verified':True,'pid':pid,'catchupTopicsPerSite':12,'normalTopicsPerSite':4,'unitSha':hashlib.sha256(unit.read_bytes()).hexdigest(),'services':subprocess.check_output(['systemctl','show','forum-flow','forum-flow-writer','-p','Id,MainPID,ActiveState,NRestarts'],text=True)};(root/'catchup-unit-verified.json').write_text(json.dumps(out,indent=2));print(json.dumps(out))
